def can_partition(nums: list[int]) -> bool:
    if not nums:
        return False

    _sum = sum(nums)
    div, mod = divmod(_sum, 2)
    if mod != 0:
        return False

    target = [div] * 2
    nums.sort(reverse=True)

    def dfs(index: int, target: list[int]) -> bool:
        if index == len(nums):
            return target[0] == 0 and target[1] == 0
        num = nums[index]
        for i in range(2):
            if target[i] >= num:
                target[i] -= num
                if dfs(index + 1, target):
                    return True
                target[i] += num
        return False

    return dfs(0, target)
