def min_insertions_to_palindrome(s: str) -> int:
    dict_hash = {}
    length_string = len(s)

    # Count the frequency of each character in the string
    for ch in s:
        if ch in dict_hash:
            dict_hash[ch] += 1
        else:
            dict_hash[ch] = 1

    # Count the number of characters with odd frequencies
    odd_count = 0
    for key in dict_hash:
        if dict_hash[key] % 2 != 0:
            odd_count += 1

    # The minimum insertions required is the number of odd frequency characters
    return odd_count
